// Build-time only. Generates js/live-sim-data-it.js — an Italian overlay for the live-sim
// commentary — by zipping the Italian arrays below (by index) with the EXACT English source
// strings in js/live-sim-data.js. Keying the output by the exact English string means the
// runtime lookup can never silently mismatch, and any English line left untranslated simply
// falls back to English. Re-run after editing either this file or the workbook export:
//   node scripts/gen-live-sim-it.mjs
// Placeholders (XY = the named client, "xy (player's team)"/"yx (opposition team)" = teams)
// are preserved verbatim so live-sim.js's substitution still fires. As in the other overlays the
// wrapping quotation marks of the English source are dropped; the feed supplies its own styling.
import { readFileSync, writeFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

